{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Codeine, which shares the query's methoxy-substituted aromatic ring and N-methyl tertiary amine, has an absolute oral bioavailability of 42–71% in healthy volunteers, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ethylmorphine, another 3-alkoxy N-methyl morphinan, showed a median systemic availability of 0.74 (range 0.54–0.92) after oral dosing, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Samidorphan, a 14-hydroxy morphinan with a related fused-ring scaffold, had an absolute oral bioavailability of 69% in healthy volunteers, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Naltrexone has a low absolute oral bioavailability of about 5%, but this is associated with its free phenol and N-cyclopropylmethyl substituents that promote extensive first-pass metabolism; these features are absent in the methoxy N-methyl query, so this low-F evidence transfers poorly.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high: the query is a methoxy N-methyl morphinan, and close analogues with the same key substituents (codeine, ethylmorphine, samidorphan) show oral bioavailability well above 20%. The low-F naltrexone data are poorly transferable because its phenol and N-cyclopropylmethyl groups create first-pass liabilities not present in the query.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability record for the exact query molecule was provided; the prediction relies on structurally related morphinans.",
    "First-pass metabolism and transporter effects specific to the query's 6-keto-14-hydroxy motif are not directly measured in the cited records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

